 if(S.modal&&S.modal.startsWith('dc-sheet-')){const kind=S.modal.slice(9);if(kind==='stool'&&!x.id&&S.dc.intake)return dialog('Review stool photos',dcSheet(kind,x),true);return dialog((x.id?'Edit ':'Add ')+(DC_KINDS[kind]?DC_KINDS[kind][0]:kind),dcSheet(kind,x));}
