 if(S.modal==='dc-obs-correct'){return dialog('Correct the camera observation',`<form id="dc-obs-correct-form"><input type="hidden" name="id" value="${x.id}"/><label class="field">What was actually happening?<select name="corrected_kind">${['movement','active','low_activity','presence','no_presence','rest','standing','sitting','walking_like','crawling_like'].map(k=>`<option value="${k}">${k.replace('_',' ')}</option>`).join('')}</select></label>${field('Note','note','text','',false,'maxlength="500"')}<div class="formfoot"><button class="btn">Save correction</button></div></form>`);}
 if(S.modal==='dc-cam-journal'){return dialog('Add camera observation to the journal',`<form id="dc-cam-journal-form"><input type="hidden" name="id" value="${x.id}"/><p class="muted" style="font-size:13px">${esc(x.label||'')}</p><label class="field">Add as<select name="as_kind"><option value="activity" ${x.suggested==='activity'?'selected':''}>Activity</option><option value="sleep" ${x.suggested==='sleep'?'selected':''}>Sleep / rest</option></select></label><label class="field">Activity kind<select name="activity_kind">${['playing','awake','walking','crawling','sitting','feeding','outdoor','exercise','tummy_time','other'].map(k=>`<option value="${k}">${k.replace('_',' ')}</option>`).join('')}</select></label>${field('Note','note','text','',false,'maxlength="500"')}<div class="alert">This confirms the observation and creates a journal entry marked “camera confirmed”. Nothing from the camera enters the journal without this step.</div><div class="formfoot"><button class="btn">Add to journal</button></div></form>`);}
