const dcBaseRender=render;
/* A background load can finish while a dialog is open; keep what the parent already typed across that re-render. */
function dcSnapModal(){const m=document.querySelector('.modal');if(!m)return null;const v={};m.querySelectorAll('input,select,textarea').forEach((x,i)=>{if(x.type==='file'||x.type==='hidden'||!x.name&&!x.id)return;const k=(x.closest('form')?.id||'')+'|'+(x.name||x.id)+'|'+(x.type==='radio'||x.type==='checkbox'?x.value:'');v[k]=x.type==='radio'||x.type==='checkbox'?x.checked:x.value;});return {modal:S.modal,v,focus:document.activeElement&&m.contains(document.activeElement)?((document.activeElement.closest('form')?.id||'')+'|'+(document.activeElement.name||document.activeElement.id)):null};}
function dcRestoreModal(snap){if(!snap||snap.modal!==S.modal)return;const m=document.querySelector('.modal');if(!m)return;m.querySelectorAll('input,select,textarea').forEach(x=>{if(x.type==='file'||x.type==='hidden')return;const base=(x.closest('form')?.id||'')+'|'+(x.name||x.id);const k=base+'|'+(x.type==='radio'||x.type==='checkbox'?x.value:'');if(k in snap.v){if(x.type==='radio'||x.type==='checkbox')x.checked=snap.v[k];else x.value=snap.v[k];}if(snap.focus===base&&x.type!=='radio')x.focus();});}
render=function(){const snap=dcSnapModal();try{dcRender();}finally{dcRestoreModal(snap);}};
function dcRender(){if(!S.token)dcReset();if(S.token&&S.patients.length&&['care','calendar','camera'].includes(S.tab)){el('#app').innerHTML=layout(S.tab==='care'?careView():S.tab==='calendar'?calendarView():cameraView());if(typeof PC!=='undefined'&&PC.bind)PC.bind(document);dcLoadThumbs();return;}dcBaseRender();if(S.token)dcLoadThumbs();}
const dcBaseReload=reload;
reload=async function(){await dcBaseReload();if(!dcAuthed()){dcReset();return;}if(DCL.pid!==S.pid){dcReset();DCL.pid=S.pid;}else{dcInvalidate(['day:','meds:','month:','week:','analytics:','illnesses:','compare:','photos:']);S.dc.todayLoaded=false;}await dcEnsure();};
/* After a Daily Health mutation: invalidate once, then load only what the current view needs (one GET per resource). */
async function dcRefresh(){dcInvalidate(['day:','meds:','month:','week:','analytics:','illnesses:','compare:','photos:']);S.dc.dayData=null;S.dc.todayData=null;S.dc.todayLoaded=false;S.dc.medsToday=null;S.dc.monthData=null;S.dc.weekData=null;S.dc.analytics=null;S.dc.analyticsRange=null;await dcEnsure();if(!['today','care','calendar'].includes(S.tab))render();}
const dcBaseExecute=execute;
execute=async function(action,id,b){
 if(action==='logout'){dcReset();return dcBaseExecute(action,id,b);}
 if(!action||!action.startsWith('dc-'))return dcBaseExecute(action,id,b);
 if(action==='dc-retry'){DCL.error=null;if(DCL.timer){clearTimeout(DCL.timer);DCL.timer=null;}DCL.cooldownUntil=0;return dcEnsure();}
 const pid=S.pid;
 switch(action){
  case 'dc-tab':S.dc.tab=b.dataset.key;if(S.tab!=='care')S.tab='care';render();return dcEnsure();
  case 'dc-filter':{const f=b.dataset.filter;S.dc.filters=f==='all'?['all']:(S.dc.filters.includes(f)?S.dc.filters.filter(x=>x!==f):[...S.dc.filters.filter(x=>x!=='all'),f]);if(!S.dc.filters.length)S.dc.filters=['all'];if(S.tab==='today'){S.tab='care';S.dc.tab='journal';}render();return;}
  case 'dc-prev':case 'dc-next':case 'dc-today':{S.dc.day=action==='dc-today'?dcToday():dcShift(S.dc.day||dcToday(),action==='dc-prev'?-1:1);S.dc.dayData=null;S.dc.medsToday=null;render();return dcEnsure();}
  case 'dc-open-day':{S.dc.day=b.dataset.day;S.dc.calView='day';S.dc.dayData=null;S.tab='calendar';render();window.scrollTo({top:0,behavior:'smooth'});return dcEnsure();}
  case 'dc-calview':S.dc.calView=b.dataset.key;render();return dcEnsure();
  case 'dc-month':{const d=new Date(S.dc.month.y,S.dc.month.m-1+Number(b.dataset.dir),1);S.dc.month={y:d.getFullYear(),m:d.getMonth()+1};render();return dcEnsure();}
  case 'dc-week':{S.dc.week=dcShift((S.dc.weekData||{}).start||S.dc.week||dcToday(),7*Number(b.dataset.dir));render();return dcEnsure();}
  case 'dc-range':S.dc.range=b.dataset.key;S.dc.analytics=null;render();return dcEnsure();
  case 'dc-photo-range':S.dc.photoDays=Number(b.dataset.days);S.dc.photoHistory=null;render();return dcEnsure();
  case 'dc-intake-more':el('#dc-intake-files')?.click();return;
  case 'dc-intake-edit-time':{const w=document.querySelector(`#dc-intake-${id} .dc-when`);if(w){w.classList.remove('collapsed');w.querySelector('input').focus();}b.remove();return;}
  case 'dc-intake-discard':{await request(`/care/stool-intake/${id}`,{method:'DELETE'});const c=S.dc.intake.items.find(x=>x.id===+id);if(c)c.status='discarded';if(!S.dc.intake.items.some(x=>x.status!=='discarded')){dcIntakeReset();S.modal='';toast('Photos discarded.');render();return;}render();return;}
  case 'dc-intake-open':{dcIntakeReset();S.modal='';S.dc.day=b.dataset.day||S.dc.day;S.dc.dayData=null;render();await dcRefresh();return execute('dc-stool',id,b);}
  case 'dc-intake-close':{const pending=S.dc.intake?S.dc.intake.items.filter(c=>c.status==='pending').length:0;if(pending&&!confirm(`${pending} photo${pending===1?'':'s'} not confirmed yet. Close anyway? They stay available for 48 hours.`))return;dcIntakeReset();S.modal='';render();return dcRefresh();}
  case 'dc-intake-confirm-all':{const forms=[...document.querySelectorAll('form.dc-intake-form')];let ok=0,bad=0;for(const f of forms){if(!f.reportValidity()){bad++;continue;}try{await dcIntakeConfirm(f);ok++;}catch(e){bad++;fail(e);}}render();toast(`${ok} stool entr${ok===1?'y':'ies'} saved${bad?`, ${bad} need attention`:''}.`);if(!bad){dcIntakeReset();S.modal='';render();}return dcRefresh();}
  case 'dc-add':{if(b.dataset.kind==='stool'){dcIntakeReset();try{const r=await request(`/patients/${pid}/care/stool/intake`);if(r.items.some(c=>c.status==='pending'||c.status==='duplicate')){S.dc.intake=r;setTimeout(()=>dcIntakeUpload([]),0);for(const c of r.items){request(`/care/stool-intake/${c.id}/image`).then(async res=>{S.dc.intakeThumbs[c.id]=URL.createObjectURL(await res.blob());const img=document.querySelector(`[data-intake="${c.id}"] .dc-intake-thumb`);if(img){const n=document.createElement('img');n.className='dc-intake-thumb';n.src=S.dc.intakeThumbs[c.id];img.replaceWith(n);}}).catch(()=>{});}}}catch(e){}}if(!S.dc.settings)await dcLoadSettings();if(b.dataset.kind==='medicine'&&!S.dc.medsToday)await dcLoadMedsToday(dcToday());return openModal('dc-sheet-'+b.dataset.kind,{});}
  case 'dc-edit':{const kind=b.dataset.kind;const rows=await request(`/patients/${pid}/care/${kind}?start=${S.dc.day||dcToday()}&end=${S.dc.day||dcToday()}`);let x=rows.find(r=>r.id===+id);if(!x){const h=await request(`/care/${kind}/${id}/history`);x=h.current;}return openModal('dc-sheet-'+kind,x);}
  case 'dc-withdraw':if(!confirm('Withdraw this entry? It stays in the history as withdrawn.'))return;await request(`/care/${b.dataset.kind}/${id}/withdraw`,{method:'POST'});S.modal='';toast('Entry withdrawn.');return dcRefresh();
  case 'dc-amount':{const f=b.closest('form');f.elements.amount_ml.value=b.dataset.ml;b.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));if(b.dataset.ml==='')f.elements.custom_amount.placeholder='Unknown amount';return;}
  case 'dc-dose':{const body={action:b.dataset.act,medicine_id:b.dataset.mid&&b.dataset.mid!=='null'&&b.dataset.mid!=='undefined'?Number(b.dataset.mid):null,medicine_name:b.dataset.name||'',scheduled_for:b.dataset.sched||null,client_key:dcKey()};await request(`/patients/${pid}/care/medicine/quick`,{method:'POST',json:body});toast(`${b.dataset.name}: recorded as ${b.dataset.act}.`);S.dc.medsToday=null;return dcRefresh();}
  case 'dc-stool':{S.modal='dc-stool-detail';S.dc.sheet=null;render();const dday=b.dataset.day||S.dc.day||dcToday();const rows=await request(`/patients/${pid}/care/stool?start=${dday}&end=${dday}`);let s=rows.find(r=>r.id===+id)||(await request(`/care/stool/${id}/history`)).current;S.dc.sheet=s;if(S.dc.photoUrl)URL.revokeObjectURL(S.dc.photoUrl);S.dc.photoUrl=null;if(s.photos?.length){try{const r=await request(`/care/stool-photos/${s.photos[0].id}`);S.dc.photoUrl=URL.createObjectURL(await r.blob());}catch(e){}}render();return;}
  case 'dc-photo-open':{const r=await request(`/care/stool-photos/${id}`);const u=URL.createObjectURL(await r.blob());window.open(u,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(u),60000);return;}
  case 'dc-photo-del':if(!confirm('Delete this photograph permanently?'))return;await request(`/care/stool-photos/${id}`,{method:'DELETE'});toast('Photo deleted.');return execute('dc-stool',S.dc.sheet.id,b);
  case 'dc-obs-stool':await request(`/care/stool/${id}/observation-review`,{method:'POST',json:{action:b.dataset.act}});toast('Observation '+b.dataset.act+'ed.');await dcRefresh();return execute('dc-stool',id,b);
  case 'dc-export-preview':{const f=el('#dc-export-form');const q=dcExportQuery(new FormData(f));const r=await request(`/patients/${pid}/care/export?${q}`);el('#dc-export-preview').innerHTML=`<div class="pre section-gap">${esc(r.summary_text)}</div>`;return;}
  case 'dc-cam-new':return openModal('dc-camera-form',{});
  case 'dc-cam-edit':return openModal('dc-camera-form',S.dc.cameras.cameras.find(c=>c.id===+id));
  case 'dc-cam-test':{const r=await request(`/cameras/${id}/test`,{method:'POST'});toast((r.ok?'Connected: ':'Not connected: ')+r.detail+` (${r.latency_ms} ms)`);dcInvalidate(['cameras:','camobs:']);await dcLoadCameras();render();return;}
  case 'dc-cam-preview':{try{const r=await request(`/cameras/${id}/preview`);S.dc.preview={id:+id,url:URL.createObjectURL(await r.blob())};}catch(e){fail(e);}render();return;}
  case 'dc-cam-disable':await request(`/cameras/${id}/disable`,{method:'POST'});toast('Camera disabled. The worker stops at its next heartbeat.');dcInvalidate(['cameras:','camobs:']);await dcLoadCameras();render();return;
  case 'dc-cam-enable':await request(`/cameras/${id}`,{method:'PATCH',json:{enabled:true}});dcInvalidate(['cameras:','camobs:']);await dcLoadCameras();render();return;
  case 'dc-cam-key':if(!confirm('Issue a new worker key? Any previous key stops working.'))return;S.dc.workerKey=await request(`/cameras/${id}/worker-key`,{method:'POST'});dcInvalidate(['cameras:','camobs:']);await dcLoadCameras();render();return;
  case 'dc-cam-purge':if(!confirm('Delete all stored clips for this camera?'))return;{const r=await request(`/cameras/${id}/purge-recordings`,{method:'POST'});toast(`${r.deleted_clips} clip(s) deleted.`);}return;
  case 'dc-cam-delete':if(!confirm('Remove this camera and its stored credentials?'))return;await request(`/cameras/${id}`,{method:'DELETE'});dcInvalidate(['cameras:','camobs:']);await dcLoadCameras();render();return;
  case 'dc-obs':{if(b.dataset.act==='correct')return openModal('dc-obs-correct',{id});await request(`/camera-observations/${id}/review`,{method:'POST',json:{action:b.dataset.act}});dcInvalidate(['cameras:','camobs:']);await dcLoadCameras();render();return;}
  case 'dc-cam-journal':{const o=S.dc.obs.find(x=>x.id===+id)||{};return openModal('dc-cam-journal',{id,label:o.label?`${o.started_at} · ${o.effective_kind} (${o.confidence_pct}%)`:'',suggested:o.suggested_journal_kind});}
 }
 return dcBaseExecute(action,id,b);};
function dcExportQuery(fd){const preset=fd.get('preset');const q=new URLSearchParams({preset,format:'json'});if(preset==='illness'&&fd.get('illness')){const [k,i]=fd.get('illness').split(':');q.set('kind',k);q.set('ref_id',i);}if(preset==='custom'){q.set('start',fd.get('start'));q.set('end',fd.get('end'));}if(fd.get('include_photos'))q.set('include_photos','true');return q.toString();}
const dcBaseSubmit=submitForm;
submitForm=async function(f){const fd=new FormData(f),o=Object.fromEntries(fd);const pid=S.pid;const fid=f.getAttribute('id');
 if(fid&&fid.startsWith('dc-intake-')){const saved=await dcIntakeConfirm(f);const left=S.dc.intake.items.filter(c=>c.status==='pending').length;toast(saved.review_message?`Saved at ${(saved.at||'').slice(11,16)} on ${fmt(saved.local_date)}. ${saved.review_message} — not a diagnosis.`:`Saved at ${(saved.at||'').slice(11,16)} on ${fmt(saved.local_date)}.`);if(!left){dcIntakeReset();S.modal='';}render();return dcRefresh();}
 const entryKinds={'dc-fluid-form':'fluid','dc-diaper-form':'diaper','dc-stool-form':'stool','dc-medicine-form':'medicine','dc-symptom-form':'symptom','dc-activity-form':'activity','dc-sleep-form':'sleep'};
 if(entryKinds[fid]){const kind=entryKinds[fid];const id=o.id;delete o.id;const photos=fd.getAll('photo').filter(x=>x&&x.size);const photo=photos[0];delete o.photo;if(kind==='stool'&&!id&&!photos.length&&!o.colour&&!o.consistency&&!o.amount&&!fd.has('mucus_observed')&&!fd.has('blood_observed')&&!fd.has('watery')&&!o.symptoms&&!o.note&&!confirm('Save a stool entry with no details? Tip: use “Add potty photo(s)” to have the values suggested from a photo.'))return;for(const k of Object.keys(o))if(o[k]==='')delete o[k];for(const k of ['amount_ml','duration_minutes','medicine_id','illness_episode_id','stool_entry_id','fever_episode_id'])if(k in o)o[k]=Number(o[k]);for(const k of ['mucus_observed','blood_observed','watery','create_diaper'])if(kind==='stool')o[k]=fd.has(k);if(kind==='fluid'&&!('amount_ml' in o)&&!o.custom_amount&&o.fluid_type!=='breastmilk')o.amount_unknown=true;
  const saved=await request(id?`/care/${kind}/${id}`:`/patients/${pid}/care/${kind}`,{method:id?'PATCH':'POST',json:o});
  if(kind==='stool'&&photo&&photo.size){let r=null;for(const ph of photos){const form=new FormData();form.append('file',ph,ph.name);form.append('analyse','true');if(ph.lastModified)form.append('file_modified',new Date(ph.lastModified).toISOString());r=await request(`/care/stool/${saved.id}/photos`,{method:'POST',body:form});}toast(r.ai_observation?.consider_clinical_review?'Saved. The image description suggests considering clinical review (not a diagnosis).':'Saved with photo. Image-based observation only — not a diagnosis.');}
  else toast(id?'Entry corrected; the previous version is kept.':'Saved.');
  S.modal='';await dcRefresh();if(kind==='stool'&&photo&&photo.size)await execute('dc-stool',saved.id,f);return;}
 if(fid==='dc-photo-form'){const picked=fd.getAll('photo').filter(x=>x&&x.size);if(!picked.length)return;const replaceId=fd.get('replace');for(const ph of picked){const form=new FormData();form.append('file',ph,ph.name);form.append('analyse','true');if(ph.lastModified)form.append('file_modified',new Date(ph.lastModified).toISOString());await request(`/care/stool/${o.id}/photos`,{method:'POST',body:form});}if(replaceId){try{await request(`/care/stool-photos/${replaceId}`,{method:'DELETE'});}catch(e){}}toast(replaceId?'Photo replaced. Image-based observation only — not a diagnosis.':'Photo added. Image-based observation only — not a diagnosis.');await dcRefresh();return execute('dc-stool',o.id,f);}
 if(fid==='dc-note-form'){await request(`/patients/${pid}/care/day/${S.dc.day||dcToday()}/note`,{method:'PUT',json:{day_note:o.day_note}});toast('Day note saved.');return dcRefresh();}
 if(fid==='dc-range-form'){S.dc.customStart=o.start;S.dc.customEnd=o.end;S.dc.analytics=null;render();return dcEnsure();}
 if(fid==='dc-compare-form'){S.dc.compareKey=o.key;S.dc.window=Number(o.window);S.dc.compare=null;render();return dcEnsure();}
 if(fid==='dc-export-form'){const q=dcExportQuery(fd).replace('format=json','format=txt');return downloadEndpoint(`/patients/${pid}/care/export?${q}`,'daily-care-summary.txt');}
 if(fid==='dc-settings-form'){if(o.wet_diaper_threshold_per_day==='')o.wet_diaper_threshold_per_day=null;else o.wet_diaper_threshold_per_day=Number(o.wet_diaper_threshold_per_day);S.dc.settings=await request(`/patients/${pid}/care/settings`,{method:'PUT',json:o});toast('Settings saved.');render();return;}
 if(fid==='dc-camera-form'){const id=o.id;delete o.id;for(const k of ['enabled','local_network_only','audio_enabled','record_clips','keep_existing_password'])o[k]=fd.has(k);o.retention_days=Number(o.retention_days||7);await request(id?`/cameras/${id}`:`/patients/${pid}/cameras`,{method:id?'PUT':'POST',json:o});toast(id?'Camera updated.':'Camera added. Test the connection, then issue a worker key.');S.modal='';dcInvalidate(['cameras:','camobs:']);await dcLoadCameras();render();return;}
 if(fid==='dc-obs-correct-form'){await request(`/camera-observations/${o.id}/review`,{method:'POST',json:{action:'correct',corrected_kind:o.corrected_kind,note:o.note}});S.modal='';dcInvalidate(['cameras:','camobs:']);await dcLoadCameras();render();return;}
 if(fid==='dc-cam-journal-form'){await request(`/camera-observations/${o.id}/add-to-journal`,{method:'POST',json:{as_kind:o.as_kind,activity_kind:o.activity_kind,note:o.note}});toast('Added to the journal as camera-confirmed.');S.modal='';dcInvalidate(['cameras:','camobs:']);await dcLoadCameras();await dcRefresh();return;}
 return dcBaseSubmit(f);};

/* Navigation is the load trigger. app.js sets S.tab and renders on these events first; this listener runs afterwards. */
document.addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(b&&dcAuthed()&&['today','care','calendar','camera'].includes(S.tab))dcEnsure();});
document.addEventListener('change',e=>{if(e.target.id==='destination'&&dcAuthed()&&['today','care','calendar','camera'].includes(S.tab))dcEnsure();});
